func ptrShipmentComment(p unsafe.Pointer, c int32) any {
	r := (*shipment.ShipmentComment)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 5:
		return (**string)(unsafe.Pointer(&r.ParentCommentID))
	case 6:
		return &r.Comment
	case 7:
		return &r.Body
	case 8:
		return (*string)(unsafe.Pointer(&r.Type))
	case 9:
		return (*string)(unsafe.Pointer(&r.Visibility))
	case 10:
		return (*string)(unsafe.Pointer(&r.Priority))
	case 11:
		return (*string)(unsafe.Pointer(&r.Source))
	case 12:
		return &r.Metadata
	case 13:
		return &r.EditedAt
	case 14:
		return &r.PinnedAt
	case 15:
		return (**string)(unsafe.Pointer(&r.PinnedByID))
	case 16:
		return &r.ResolvedAt
	case 17:
		return (**string)(unsafe.Pointer(&r.ResolvedByID))
	case 18:
		return &r.RequiresAcknowledgment
	case 19:
		return &r.DeletedAt
	case 20:
		return (**string)(unsafe.Pointer(&r.DeletedByID))
	case 21:
		return &r.SearchVector
	case 22:
		return &r.ReplyCount
	case 23:
		return &r.Version
	case 24:
		return &r.CreatedAt
	case 25:
		return &r.UpdatedAt
	}
	return nil
}

func valueShipmentComment(p unsafe.Pointer, c int32) any {
	r := (*shipment.ShipmentComment)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		if r.UserID == "" {
			return nil
		}
		return string(r.UserID)
	case 5:
		if r.ParentCommentID == nil {
			return nil
		}
		return string(*r.ParentCommentID)
	case 6:
		return r.Comment
	case 7:
		if r.Body == nil {
			return nil
		}
		return r.Body
	case 8:
		return string(r.Type)
	case 9:
		return string(r.Visibility)
	case 10:
		return string(r.Priority)
	case 11:
		return string(r.Source)
	case 12:
		if r.Metadata == nil {
			return keel.EmptyJSONObject
		}
		return r.Metadata
	case 13:
		if r.EditedAt == nil {
			return nil
		}
		return *r.EditedAt
	case 14:
		if r.PinnedAt == nil {
			return nil
		}
		return *r.PinnedAt
	case 15:
		if r.PinnedByID == nil {
			return nil
		}
		return string(*r.PinnedByID)
	case 16:
		if r.ResolvedAt == nil {
			return nil
		}
		return *r.ResolvedAt
	case 17:
		if r.ResolvedByID == nil {
			return nil
		}
		return string(*r.ResolvedByID)
	case 18:
		return r.RequiresAcknowledgment
	case 19:
		if r.DeletedAt == nil {
			return nil
		}
		return *r.DeletedAt
	case 20:
		if r.DeletedByID == nil {
			return nil
		}
		return string(*r.DeletedByID)
	case 21:
		return r.SearchVector
	case 22:
		return r.ReplyCount
	case 23:
		return r.Version
	case 24:
		return r.CreatedAt
	case 25:
		return r.UpdatedAt
	}
	return nil
}

func attachShipmentComment(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*shipment.ShipmentComment)(p)
	switch rel {
	case 0:
		r.User = (*tenant.User)(child)
	case 1:
		r.PinnedBy = (*tenant.User)(child)
	case 2:
		r.ResolvedBy = (*tenant.User)(child)
	case 3:
		r.MentionedUsers = append(r.MentionedUsers, (*shipment.ShipmentCommentMention)(child))
	case 4:
		r.Acknowledgments = append(r.Acknowledgments, (*shipment.ShipmentCommentAcknowledgment)(child))
	}
}

func beforeCreateShipmentComment(ctx context.Context, p unsafe.Pointer) error {
	return (*shipment.ShipmentComment)(p).BeforeCreate(ctx)
}

