func newShipmentCommodity() unsafe.Pointer { return unsafe.Pointer(new(shipment.ShipmentCommodity)) }

func newNShipmentCommodity(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]shipment.ShipmentCommodity, n)))
}

func ptrShipmentCommodity(p unsafe.Pointer, c int32) any {
	r := (*shipment.ShipmentCommodity)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.CommodityID))
	case 5:
		return &r.Weight
	case 6:
		return &r.Pieces
	case 7:
		return &r.LengthFeet
	case 8:
		return &r.WidthFeet
	case 9:
		return &r.HeightFeet
	case 10:
		return &r.Version
	case 11:
		return &r.CreatedAt
	case 12:
		return &r.UpdatedAt
	}
	return nil
}

func valueShipmentCommodity(p unsafe.Pointer, c int32) any {
	r := (*shipment.ShipmentCommodity)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.CommodityID)
	case 5:
		return r.Weight
	case 6:
		return r.Pieces
	case 7:
		if r.LengthFeet == nil {
			return nil
		}
		return *r.LengthFeet
	case 8:
		if r.WidthFeet == nil {
			return nil
		}
		return *r.WidthFeet
	case 9:
		if r.HeightFeet == nil {
			return nil
		}
		return *r.HeightFeet
	case 10:
		return r.Version
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	}
	return nil
}

func attachShipmentCommodity(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*shipment.ShipmentCommodity)(p)
	switch rel {
	case 0:
		r.Shipment = (*shipment.Shipment)(child)
	case 1:
		r.Commodity = (*commodity.Commodity)(child)
	}
}

