func newStop() unsafe.Pointer { return unsafe.Pointer(new(shipment.Stop)) }

func newNStop(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]shipment.Stop, n)))
}

func ptrStop(p unsafe.Pointer, c int32) any {
	r := (*shipment.Stop)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentMoveID))
	case 4:
		return (*string)(unsafe.Pointer(&r.LocationID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return (*string)(unsafe.Pointer(&r.Type))
	case 7:
		return (*string)(unsafe.Pointer(&r.ScheduleType))
	case 8:
		return &r.Sequence
	case 9:
		return &r.Pieces
	case 10:
		return &r.Weight
	case 11:
		return &r.ScheduledWindowStart
	case 12:
		return &r.ScheduledWindowEnd
	case 13:
		return &r.ActualArrival
	case 14:
		return &r.ActualDeparture
	case 15:
		return &r.CountLateOverride
	case 16:
		return &r.CountDetentionOverride
	case 17:
		return &r.AddressLine
	case 18:
		return &r.Version
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueStop(p unsafe.Pointer, c int32) any {
	r := (*shipment.Stop)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentMoveID)
	case 4:
		return string(r.LocationID)
	case 5:
		return string(r.Status)
	case 6:
		return string(r.Type)
	case 7:
		return string(r.ScheduleType)
	case 8:
		return r.Sequence
	case 9:
		if r.Pieces == nil {
			return nil
		}
		return *r.Pieces
	case 10:
		if r.Weight == nil {
			return nil
		}
		return *r.Weight
	case 11:
		return r.ScheduledWindowStart
	case 12:
		if r.ScheduledWindowEnd == nil {
			return nil
		}
		return *r.ScheduledWindowEnd
	case 13:
		if r.ActualArrival == nil {
			return nil
		}
		return *r.ActualArrival
	case 14:
		if r.ActualDeparture == nil {
			return nil
		}
		return *r.ActualDeparture
	case 15:
		if r.CountLateOverride == nil {
			return nil
		}
		return *r.CountLateOverride
	case 16:
		if r.CountDetentionOverride == nil {
			return nil
		}
		return *r.CountDetentionOverride
	case 17:
		if r.AddressLine == "" {
			return nil
		}
		return r.AddressLine
	case 18:
		return r.Version
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

func attachStop(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*shipment.Stop)(p)
	switch rel {
	case 0:
		r.Location = (*location.Location)(child)
	}
}

func beforeCreateStop(ctx context.Context, p unsafe.Pointer) error {
	return (*shipment.Stop)(p).BeforeCreate(ctx)
}

func beforeUpdateStop(ctx context.Context, p unsafe.Pointer) error {
	return (*shipment.Stop)(p).BeforeUpdate(ctx)
}

